S = "Hakeem Force Academy"
RAW = []
def A(q, right, wrong, reason, rel):
    RAW.append((q, right, wrong, reason, rel))

A("Under which Article of the 1973 Constitution is the office of the President of Pakistan established?", "Article 41", ["Article 40", "Article 42", "Article 44"], "Article 41 says there shall be a President of Pakistan who is the Head of State and represents the unity of the Republic.", "The President must be a Muslim of at least 45 years of age and qualified to be elected as a member of the National Assembly.")
A("What is the minimum age to be elected President of Pakistan under Article 41(2)?", "45 years", ["35 years", "40 years", "50 years"], "Article 41(2) requires a Muslim, qualified to be a National Assembly member, who is not less than 45 years old.", "The minimum age for a Prime Minister is the same as for a National Assembly member, that is 25 years.")
A("Which Article of the 1973 Constitution contains the oath of office of the President?", "Article 42", ["Article 41", "Article 43", "Article 45"], "Article 42 provides that before entering office the President makes the oath in the form set out in the Third Schedule.", "The President takes the oath before the Chief Justice of Pakistan.")
A("Who administers the oath of office to the President of Pakistan?", "The Chief Justice of Pakistan", ["The Speaker of the National Assembly", "The Prime Minister", "The Chairman of the Senate"], "Article 42 states that the oath is administered by the Chief Justice of Pakistan, or in his absence by the senior most judge of the Supreme Court.", "The Prime Minister takes the oath under Article 91 before the President.")
A("Under which Article can the President grant pardon, reprieve and respite and remit, suspend or commute any sentence?", "Article 45", ["Article 46", "Article 48", "Article 49"], "Article 45 gives the President the power to grant pardon, reprieve and respite, and to remit, suspend or commute a sentence passed by any court, tribunal or authority.", "Article 46 deals with the President's right to be kept informed by the Prime Minister.")
A("Under which Article of the 1973 Constitution can the President be removed or impeached?", "Article 47", ["Article 45", "Article 48", "Article 50"], "Article 47 allows removal of the President for physical or mental incapacity or for violating the Constitution or gross misconduct.", "The impeachment resolution must be passed by not less than two thirds of the total membership of the Majlis-e-Shoora (Parliament) in a joint sitting.")
A("What majority of the total membership of Parliament in a joint sitting is needed to impeach the President under Article 47?", "Two thirds", ["Simple majority", "Three fourths", "Three fifths"], "Article 47(3) requires a resolution passed by not less than two thirds of the total membership of the Majlis-e-Shoora.", "The notice of the impeachment motion must be signed by not less than half of the members of either House.")
A("Which Article of the 1973 Constitution lays down that the President shall act on the advice of the Cabinet or the Prime Minister?", "Article 48", ["Article 46", "Article 49", "Article 90"], "Article 48(1) says that in the exercise of his functions the President shall act on and in accordance with the advice of the Cabinet or the Prime Minister.", "Article 48(6) allows the President to refer a matter of national importance to a referendum.")
A("Under which Article can the President refer a matter of national importance to a referendum?", "Article 48(6)", ["Article 45", "Article 47", "Article 58"], "Article 48(6) lets the President, after consulting the Prime Minister, direct a referendum on a question of national importance.", "The result of the referendum is placed before the Majlis-e-Shoora.")
A("Under Article 49, who acts as President when the office of the President is vacant?", "The Chairman of the Senate", ["The Prime Minister", "The Chief Justice of Pakistan", "The Chief of Army Staff"], "Article 49 provides that the Chairman of the Senate, or in his absence the Speaker of the National Assembly, acts as President.", "A new President must be elected within 30 days of the vacancy.")
A("Which Article of the 1973 Constitution describes the Majlis-e-Shoora (Parliament) as consisting of the President and two Houses?", "Article 50", ["Article 41", "Article 51", "Article 59"], "Article 50 states that the Majlis-e-Shoora consists of the President, the National Assembly and the Senate.", "The two Houses are the National Assembly (lower house) and the Senate (upper house).")
A("Under which Article is the National Assembly constituted and its seats distributed?", "Article 51", ["Article 50", "Article 52", "Article 59"], "Article 51 deals with the composition of the National Assembly and the allocation of general, women and non-Muslim seats.", "After the 25th Amendment (2018) the National Assembly has 336 seats: 266 general, 60 women and 10 non-Muslim.")
A("How many general seats does Punjab hold in the National Assembly after the 25th Amendment of 2018?", "141", ["148", "173", "131"], "After the merger of FATA the general seats became 266 and Punjab holds 141 of them.", "Sindh has 61, Khyber Pakhtunkhwa 45, Balochistan 16 and Islamabad 3 general seats.")
A("How many general seats does Sindh hold in the National Assembly after the 25th Amendment?", "61", ["75", "51", "70"], "Under Article 51 as amended in 2018, Sindh has 61 of the 266 general seats.", "The 12 FATA seats were abolished by the 25th Amendment, reducing the National Assembly from 342 to 336 members.")
A("What is the normal term of the National Assembly under Article 52?", "Five years", ["Four years", "Six years", "Three years"], "Article 52 says the National Assembly continues for five years from the day of its first meeting unless sooner dissolved.", "The Senate is a permanent house and cannot be dissolved.")
A("What is the quorum of the National Assembly under Article 55?", "One fourth of the total membership", ["One half of the total membership", "One third of the total membership", "One fifth of the total membership"], "Article 55 fixes the quorum for a meeting of a House at one fourth of its total membership.", "The same quorum rule applies to the Senate.")
A("Under Article 64, after how many consecutive days of absence without leave can a member's seat be declared vacant?", "40 days", ["30 days", "60 days", "90 days"], "Article 64(1)(b) provides that a member absent for forty consecutive days of a session without leave of the House can have the seat declared vacant.", "A member may also resign by writing to the Speaker.")
A("Under which Article can the President dissolve the National Assembly on the advice of the Prime Minister?", "Article 58", ["Article 48", "Article 52", "Article 89"], "Article 58(1) allows dissolution on the advice of the Prime Minister, and the Assembly stands dissolved after 48 hours if the President does not act.", "The discretionary power of dissolution in Article 58(2)(b) was inserted by the 8th Amendment (1985) and removed by the 18th Amendment (2010).")
A("Which Amendment first inserted Article 58(2)(b), the President's discretionary power to dissolve the National Assembly?", "8th Amendment (1985)", ["4th Amendment (1975)", "13th Amendment (1997)", "17th Amendment (2003)"], "The 8th Amendment of 1985, passed under General Zia, added Article 58(2)(b).", "The 13th Amendment (1997) repealed it, the 17th (2003) restored it and the 18th (2010) removed it for good.")
A("Which Amendment repealed Article 58(2)(b) in 1997 under Prime Minister Nawaz Sharif?", "13th Amendment", ["12th Amendment", "14th Amendment", "15th Amendment"], "The 13th Amendment (April 1997) removed the President's power to dissolve the National Assembly at discretion.", "The 14th Amendment of 1997 introduced the anti-defection Article 63A.")
A("Within how many days must elections be held after the National Assembly is dissolved before its term ends, under Article 224?", "90 days", ["60 days", "30 days", "120 days"], "Article 224(2) requires a general election within ninety days of the dissolution.", "If the Assembly completes its term, elections must be held within 60 days of its expiry (Article 224(1)).")
A("Which Article of the 1973 Constitution lays down the qualifications for membership of Parliament?", "Article 62", ["Article 60", "Article 61", "Article 63"], "Article 62 sets the qualifications, such as citizenship, age, good character and sagacious, honest and righteous conduct.", "Article 63 lists the disqualifications.")
A("What is the minimum age to be elected as a member of the Senate under Article 62?", "30 years", ["25 years", "35 years", "40 years"], "Article 62(1)(b) requires a Senate member to be not less than thirty years of age.", "For the National Assembly and Provincial Assemblies the minimum age is 25 years.")
A("What is the minimum age to be elected as a member of the National Assembly?", "25 years", ["21 years", "30 years", "35 years"], "Article 62(1)(b) requires a National Assembly member to be not less than twenty five years old and enrolled as a voter.", "The voting age in Pakistan is 18 years.")
A("Which Article of the 1973 Constitution lists the disqualifications for membership of Parliament?", "Article 63", ["Article 62", "Article 64", "Article 65"], "Article 63 lists grounds such as unsound mind, loss of citizenship, conviction for moral turpitude and holding an office of profit.", "Article 62(1)(f) requires a member to be sagacious, righteous, non-profligate, honest and ameen.")
A("Which Article of the 1973 Constitution deals with disqualification on grounds of defection?", "Article 63A", ["Article 63", "Article 62", "Article 64"], "Article 63A was inserted by the 14th Amendment of 1997 to disqualify members who defect from their party.", "Article 62 lays down qualifications and Article 63 disqualifications of members.")
A("Which Amendment inserted the anti-defection Article 63A in the Constitution?", "14th Amendment (1997)", ["8th Amendment (1985)", "13th Amendment (1997)", "18th Amendment (2010)"], "The 14th Amendment of 1997 added Article 63A to stop floor crossing by members of political parties.", "Article 63A follows Article 63, which lists disqualifications.")
A("How many members does the Senate have today?", "96", ["104", "100", "87"], "After the 25th Amendment (2018) removed the 8 FATA seats, the Senate fell from 104 to 96 members.", "Each province has 23 senators and Islamabad has 4.")
A("How many senators represent each province in the Senate after the 25th Amendment?", "23", ["14", "22", "26"], "Each province has 14 general, 4 women, 4 technocrat and 1 non-Muslim seat, that is 23 in all.", "Islamabad has 4 senators, making 4 x 23 + 4 = 96.")
A("What is the term of a member of the Senate?", "Six years", ["Four years", "Five years", "Three years"], "A senator serves six years and half of the members retire every three years.", "The Senate cannot be dissolved.")
A("Under which Article is the Chairman of the Senate elected?", "Article 60", ["Article 59", "Article 53", "Article 61"], "Article 60 provides that the Senate elects a Chairman and Deputy Chairman from among its members.", "Article 53 provides the same for the Speaker and Deputy Speaker of the National Assembly.")
A("Under which Article is the Speaker of the National Assembly elected?", "Article 53", ["Article 51", "Article 52", "Article 54"], "Article 53 requires the National Assembly to elect a Speaker and a Deputy Speaker from among its members as soon as possible after the general election.", "Article 54 deals with summoning and proroguing the Houses.")
A("Which Article of the 1973 Constitution gives the President power to promulgate Ordinances when Parliament is not in session?", "Article 89", ["Article 75", "Article 88", "Article 128"], "Article 89 allows the President to issue an Ordinance when neither the National Assembly nor the Senate is in session and immediate action is needed.", "A Governor issues provincial Ordinances under Article 128.")
A("For how long does a Federal Ordinance remain in force under Article 89 unless extended?", "120 days", ["90 days", "60 days", "180 days"], "Article 89(2) says an Ordinance stops after one hundred and twenty days, and the National Assembly may extend it once for another 120 days.", "A provincial Ordinance under Article 128 lasts 90 days.")
A("For how long does a Provincial Ordinance issued by the Governor remain in force under Article 128 unless extended?", "90 days", ["60 days", "120 days", "30 days"], "Article 128 limits a Governor's Ordinance to ninety days, extendable once by the Provincial Assembly for up to 90 days.", "Federal Ordinances last 120 days under Article 89.")
A("Within how many days must the President give assent to a bill passed by Parliament under Article 75?", "10 days", ["7 days", "14 days", "30 days"], "Article 75 says the President must assent or return the bill with comments within ten days of receiving it.", "If he returns it and Parliament passes it again, he has to assent within ten days or it is deemed assented.")
A("Where can a Money Bill be introduced under Article 73 of the 1973 Constitution?", "Only in the National Assembly", ["Only in the Senate", "In either House", "In a joint sitting only"], "Article 73 states that a Money Bill originates only in the National Assembly.", "The Senate can only make recommendations on a Money Bill.")
A("Within how many days must the Senate give its recommendations on a Money Bill sent by the National Assembly?", "14 days", ["7 days", "10 days", "30 days"], "Article 73(2) gives the Senate fourteen days to make recommendations, which the National Assembly may accept or reject.", "The Senate cannot block a Money Bill.")
A("Under which Article is the annual budget statement laid before the National Assembly?", "Article 80", ["Article 73", "Article 78", "Article 84"], "Article 80 requires the Federal Government to lay before the National Assembly the annual statement of estimated receipts and expenditure.", "Article 78 creates the Federal Consolidated Fund and the Public Account.")
A("Which Article of the 1973 Constitution deals with the executive authority of the Federation being exercised in the name of the President?", "Article 90", ["Article 91", "Article 92", "Article 99"], "Article 90 provides that the executive authority of the Federation is exercised in the name of the President by the Federal Government through the Prime Minister and Federal Ministers.", "Article 91 describes the Cabinet and the election of the Prime Minister.")
A("Under which Article is the Prime Minister of Pakistan elected by the National Assembly?", "Article 91", ["Article 90", "Article 92", "Article 95"], "Article 91(4) says the National Assembly elects the Prime Minister by a majority of its total membership.", "x")
A("Which Article of the 1973 Constitution limits the size of the Federal Cabinet?", "Article 92", ["Article 90", "Article 91", "Article 93"], "Article 92(1) says the number of Federal Ministers and Ministers of State shall not exceed eleven percent of the total membership of Parliament.", "This 11 percent limit was added by the 18th Amendment (2010).")
A("What percentage of the total membership of Parliament may Federal Ministers and Ministers of State form, under Article 92?", "11 percent", ["10 percent", "15 percent", "20 percent"], "Article 92(1) as amended by the 18th Amendment caps the Federal Cabinet at eleven percent of Parliament's total membership.", "With 336 plus 96 members, this gives about 47 ministers.")
A("Which Article of the 1973 Constitution deals with the vote of no confidence against the Prime Minister?", "Article 95", ["Article 91", "Article 94", "Article 96"], "Article 95 provides for a resolution of no confidence moved in the National Assembly against the Prime Minister.", "It must be passed by a majority of the total membership of the National Assembly.")
A("What share of the total membership of the National Assembly must sign a no-confidence resolution against the Prime Minister under Article 95?", "Not less than 20 percent", ["Not less than 10 percent", "Not less than 33 percent", "Not less than 50 percent"], "Article 95(1) says the resolution is moved by not less than twenty percent of the total membership.", "Voting takes place not earlier than three days and not later than seven days after the resolution is moved.")
A("Under which Article does the Attorney-General for Pakistan hold office?", "Article 100", ["Article 99", "Article 101", "Article 140"], "Article 100 provides for the Attorney-General, appointed by the President, who must be qualified to be a Supreme Court judge.", "The Advocate-General of a province is appointed under Article 140.")
A("Under which Article is the Governor of a province appointed?", "Article 101", ["Article 100", "Article 102", "Article 105"], "Article 101 says the President appoints a Governor for each province after consulting the Prime Minister.", "A Governor must be a voter, at least 35 years old and a resident of that province.")
A("What is the minimum age to be appointed Governor of a province under Article 101?", "35 years", ["25 years", "30 years", "45 years"], "Article 101(2) requires a Governor to be not less than thirty five years of age and a registered voter in the province.", "The Governor holds office at the pleasure of the President.")
A("What is the total membership of the Provincial Assembly of Punjab?", "371", ["297", "341", "350"], "The Punjab Assembly has 371 members including women and non-Muslim reserved seats.", "Sindh has 168, Khyber Pakhtunkhwa 145 and Balochistan 65 members.")
A("What is the total membership of the Provincial Assembly of Sindh?", "168", ["130", "186", "155"], "The Sindh Assembly has 168 members including 130 general, 29 women and 9 non-Muslim seats.", "The Balochistan Assembly is the smallest with 65 members.")
A("What is the total membership of the Provincial Assembly of Khyber Pakhtunkhwa after the merger of FATA?", "145", ["124", "115", "171"], "After the 25th Amendment the KP Assembly rose from 124 to 145 members, including seats from the merged districts.", "The Balochistan Assembly has 65 members.")
A("What is the total membership of the Provincial Assembly of Balochistan?", "65", ["51", "75", "58"], "The Balochistan Assembly has 65 members: 51 general, 11 women and 3 non-Muslim.", "It is the smallest provincial assembly in Pakistan.")
A("Under which Article is the Chief Minister of a province elected?", "Article 130", ["Article 101", "Article 129", "Article 131"], "Article 130 provides that the Provincial Assembly elects a Chief Minister by a majority of its members.", "The Governor appoints the Chief Minister on that basis and administers the oath.")
A("Under which Article can the Governor dissolve the Provincial Assembly on the advice of the Chief Minister?", "Article 112", ["Article 58", "Article 105", "Article 128"], "Article 112 allows dissolution on the Chief Minister's advice, and the Assembly stands dissolved after 48 hours if the Governor does not act.", "Article 58 is the matching provision for the National Assembly.")
A("Which Article of the 1973 Constitution deals with local government, inserted by the 18th Amendment?", "Article 140A", ["Article 140", "Article 141", "Article 148"], "Article 140A requires each province to set up a local government system and devolve political, administrative and financial responsibility to it.", "Article 140 deals with the Advocate-General of a province.")
A("Which Amendment of 2010 renamed the North-West Frontier Province as Khyber Pakhtunkhwa?", "18th Amendment", ["17th Amendment", "19th Amendment", "20th Amendment"], "The 18th Amendment, passed in April 2010, changed the name in Article 1.", "It also abolished the Concurrent Legislative List.")
A("The 18th Amendment to the 1973 Constitution was passed in which year?", "2010", ["2008", "2012", "2003"], "The 18th Amendment was passed by Parliament in April 2010 under President Asif Ali Zardari and Prime Minister Yousaf Raza Gilani.", "It changed about 100 Articles of the Constitution.")
A("Which Article extends the Federal and Provincial laws, giving Parliament the power to make laws for whole or any part of Pakistan?", "Article 141", ["Article 142", "Article 143", "Article 144"], "Article 141 says that Parliament may make laws for the whole or any part of Pakistan, and a Provincial Assembly for its province.", "Article 142 sets out the subjects of law-making.")
A("Under which Article does the federal law prevail when a federal and a provincial law conflict?", "Article 143", ["Article 141", "Article 142", "Article 144"], "Article 143 provides that in case of inconsistency the Act of Parliament prevails and the provincial law is void to the extent of the repugnancy.", "Article 144 lets Parliament legislate for provinces with the consent of the Provincial Assemblies.")
A("Which Legislative List was abolished by the 18th Amendment?", "The Concurrent Legislative List", ["The Federal Legislative List", "The Provincial List", "The Exclusive List of the Senate"], "The 18th Amendment removed the Concurrent List from the Fourth Schedule and gave those subjects to the provinces.", "The Federal Legislative List now has Part I and Part II, the latter under the Council of Common Interests.")
A("Under which Article is the Council of Common Interests (CCI) established?", "Article 153", ["Article 151", "Article 154", "Article 156"], "Article 153 provides for the Council of Common Interests to be formed by the President.", "The Prime Minister is the chairman and the four Chief Ministers are members.")
A("How often must the Council of Common Interests meet according to Article 154?", "At least once in 90 days", ["At least once a year", "At least once in 30 days", "At least once in six months"], "Article 154(3), as changed by the 18th Amendment, requires a meeting at least once in ninety days.", "The Council is answerable to Parliament.")
A("Who is the chairman of the Council of Common Interests?", "The Prime Minister", ["The President", "The Chief Justice of Pakistan", "The Federal Finance Minister"], "Under Article 153 the Prime Minister is the chairman of the CCI.", "The Council deals with Part II of the Federal Legislative List and disputes over water and electricity.")
A("Under which Article is the National Economic Council set up?", "Article 156", ["Article 153", "Article 155", "Article 160"], "Article 156 establishes the National Economic Council to review the economic condition of the country and advise the Federal and provincial governments.", "The Prime Minister is its chairman.")
A("Which Article of the 1973 Constitution protects against interference with water supplies of any province?", "Article 155", ["Article 153", "Article 154", "Article 156"], "Article 155 deals with complaints about interference with water supplies and refers them to the Council of Common Interests.", "Article 158 gives priority in natural gas to the province where the well-head is located.")
A("Under which Article does the province where a natural gas well is located have the first priority over its needs?", "Article 158", ["Article 155", "Article 157", "Article 161"], "Article 158 says the province in which a natural gas well-head is situated has precedence over other parts of the country in meeting its requirements.", "Article 161 gives provinces the net proceeds of the gas excise duty and hydro-electric profits.")
A("Under which Article of the 1973 Constitution is the National Finance Commission (NFC) formed?", "Article 160", ["Article 158", "Article 161", "Article 165"], "Article 160 requires the President to constitute an NFC to recommend how taxes are divided between the Federation and the provinces.", "Article 160(3A) says no Award can give a province a smaller share than the previous Award.")
A("At what interval must the National Finance Commission be constituted under Article 160?", "Not exceeding five years", ["Every year", "Every ten years", "Every three years"], "Article 160(1) requires the NFC to be constituted within six months of the start of the Constitution and thereafter at intervals not exceeding five years.", "In practice the 7th NFC Award of 2010 has lasted much longer.")
A("The 7th NFC Award gave the provinces what share of the divisible pool?", "57.5 percent", ["50 percent", "42.5 percent", "60 percent"], "Under the 7th NFC Award (2010) the provinces get 57.5 percent of the divisible pool and the Federation 42.5 percent.", "Punjab gets 51.74 percent of the provincial share, Sindh 24.55, KP 14.62 and Balochistan 9.09.")
A("Which province receives the largest share in the 7th NFC Award?", "Punjab", ["Sindh", "Khyber Pakhtunkhwa", "Balochistan"], "Punjab receives 51.74 percent of the provincial share, based on a multiple criteria formula.", "The 7th NFC Award introduced a multiple criteria formula, not only population.")
A("Which Article of the 1973 Constitution provides for the Auditor-General of Pakistan?", "Article 168", ["Article 160", "Article 169", "Article 171"], "Article 168 provides that the President appoints the Auditor-General of Pakistan.", "The Auditor-General holds office for four years or until the age of 65, whichever is earlier.")
A("What is the term of office of the Auditor-General of Pakistan under Article 168?", "Four years or age 65, whichever is earlier", ["Five years or age 65", "Three years or age 62", "Until age 60"], "Article 168 fixes four years from the date of assuming office or age sixty five, whichever is earlier.", "The Auditor-General can be removed only like a Supreme Court judge.")
A("Under which Article does the Auditor-General submit his audit reports to the President?", "Article 171", ["Article 168", "Article 169", "Article 170"], "Article 171 requires the Auditor-General's reports on Federal accounts to be submitted to the President, who lays them before Parliament.", "The Public Accounts Committee of the National Assembly studies these reports.")
A("Under which Article is it laid down that no court has any jurisdiction except what the Constitution or law gives it?", "Article 175", ["Article 176", "Article 177", "Article 184"], "Article 175(2) states that no court shall have any jurisdiction save as is or may be conferred on it by the Constitution or by law.", "Article 175(3) provides for separation of the judiciary from the executive.")
A("Which Article provides for the Judicial Commission of Pakistan for appointment of judges, introduced by the 18th Amendment?", "Article 175A", ["Article 175", "Article 177", "Article 209"], "Article 175A, inserted by the 18th Amendment in 2010, set up the Judicial Commission and a parliamentary committee for appointing judges.", "The 26th Amendment (2024) changed the make-up of the commission again.")
A("Which Amendment altered the judicial appointment process by adding the Parliamentary Committee in Article 175A?", "19th Amendment", ["17th Amendment", "18th Amendment", "20th Amendment"], "The 19th Amendment (December 2010) changed Article 175A after the Supreme Court's ruling in the Nadeem Ahmad case.", "The 18th Amendment first created the Judicial Commission.")
A("Under which Article of the 1973 Constitution is the Supreme Court of Pakistan constituted?", "Article 176", ["Article 175", "Article 177", "Article 179"], "Article 176 says the Supreme Court consists of a Chief Justice and as many judges as fixed by Act of Parliament.", "Article 177 deals with appointment of judges.")
A("What is the retirement age of a Supreme Court judge under Article 179?", "65 years", ["62 years", "60 years", "68 years"], "Article 179 says a Supreme Court judge holds office until the age of sixty five.", "A High Court judge retires at 62 under Article 195.")
A("What is the retirement age of a High Court judge under Article 195?", "62 years", ["60 years", "65 years", "63 years"], "Article 195 provides that a High Court judge holds office until the age of sixty two.", "The retirement age of a Supreme Court judge is 65.")
A("What is the minimum age to be appointed a judge of a High Court under Article 193?", "45 years", ["35 years", "40 years", "50 years"], "Article 193(2)(a) requires a High Court judge to be a citizen of at least forty five years of age.", "He must also have 10 years as a High Court advocate or 10 years in civil service holding judicial office.")
A("Under which Article is the seat of the Supreme Court of Pakistan fixed at Islamabad?", "Article 183", ["Article 176", "Article 182", "Article 184"], "Article 183 says the permanent seat of the Supreme Court is at Islamabad, and it may sit at other places with the Chief Justice's approval.", "The Supreme Court has branch registries in Lahore, Karachi, Peshawar and Quetta.")
A("Which Article of the 1973 Constitution allows decisions of the Supreme Court to bind all other courts in Pakistan?", "Article 189", ["Article 187", "Article 188", "Article 190"], "Article 189 says a Supreme Court decision on a question of law, or that enunciates a principle of law, binds all other courts in Pakistan.", "Article 188 gives the Supreme Court the power to review its own judgments.")
A("Under which Article must all executive and judicial authorities in Pakistan act in aid of the Supreme Court?", "Article 190", ["Article 189", "Article 191", "Article 199"], "Article 190 states that all executive and judicial authorities throughout Pakistan shall act in aid of the Supreme Court.", "Article 191 allows the Supreme Court to make its own rules of procedure.")
A("Which Article gives the Supreme Court the power to review its own judgments?", "Article 188", ["Article 186", "Article 187", "Article 189"], "Article 188 lets the Supreme Court review any judgment pronounced or order made by it, subject to Act of Parliament and rules.", "Article 187 allows the Court to issue processes for doing complete justice in any case.")
A("Under which Article does the High Court issue writs such as habeas corpus and mandamus?", "Article 199", ["Article 184", "Article 187", "Article 203"], "Article 199 gives a High Court the power to issue directions in the nature of writs for enforcement of rights and to control the actions of authorities.", "Article 203 gives High Courts supervision over subordinate courts.")
A("Which Article gives High Courts supervisory control over the subordinate courts?", "Article 203", ["Article 199", "Article 200", "Article 204"], "Article 203 provides that each High Court supervises and controls all courts subordinate to it.", "Article 200 deals with transfer of High Court judges.")
A("Which Article of the 1973 Constitution deals with contempt of court?", "Article 204", ["Article 199", "Article 203", "Article 209"], "Article 204 gives the Supreme Court and High Courts the power to punish for contempt.", "Article 209 covers the Supreme Judicial Council.")
A("Under which Article is the Supreme Judicial Council constituted?", "Article 209", ["Article 175A", "Article 208", "Article 212"], "Article 209 creates the Supreme Judicial Council to inquire into the conduct of judges of the Supreme Court and High Courts.", "It is headed by the Chief Justice of Pakistan.")
A("Who is the chairman of the Supreme Judicial Council?", "The Chief Justice of Pakistan", ["The Attorney-General", "The President", "The senior most High Court Chief Justice"], "Article 209(2) says the Council consists of the Chief Justice of Pakistan, two next senior Supreme Court judges and two senior Chief Justices of High Courts.", "The Council can recommend the removal of a judge for incapacity or misconduct.")
A("Which Article of the 1973 Constitution provides for Administrative Courts and Tribunals?", "Article 212", ["Article 209", "Article 210", "Article 211"], "Article 212 allows Parliament or a Provincial Assembly to establish administrative courts or tribunals, with appeal to the Supreme Court.", "The Federal Service Tribunal is an example.")
A("Which Chapter of the Constitution establishes the Federal Shariat Court?", "Chapter 3A (Articles 203A to 203J)", ["Chapter 1", "Chapter 2", "Chapter 4"], "Chapter 3A of Part VII, inserted in 1980, set up the Federal Shariat Court under Articles 203A to 203J.", "It examines whether a law is repugnant to the injunctions of Islam.")
A("How many Muslim judges does the Federal Shariat Court have under Article 203C?", "Eight", ["Five", "Seven", "Twelve"], "Article 203C says the Federal Shariat Court consists of not more than eight Muslim judges, including the Chairman.", "Not more than three of them are Ulema well versed in Islamic law.")
A("Under which Article is the Chief Election Commissioner appointed?", "Article 213", ["Article 215", "Article 218", "Article 219"], "Article 213 provides for the appointment of the Chief Election Commissioner by the President from a list sent by a parliamentary committee.", "Article 215 states his term is three years.")
A("What is the term of office of the Chief Election Commissioner under Article 215?", "Three years", ["Two years", "Four years", "Five years"], "Article 215 provides that the Chief Election Commissioner holds office for three years from the day he enters upon office.", "The Chief Election Commissioner must be a retired Supreme Court judge or a person qualified to be one.")
A("Under which Article is the Election Commission of Pakistan established?", "Article 218", ["Article 213", "Article 219", "Article 224"], "Article 218 creates the Election Commission, consisting of the Chief Election Commissioner and four members, one from each province.", "Each member is a retired High Court judge.")
A("How many members besides the Chief Election Commissioner does the Election Commission have, one from each province?", "Four", ["Two", "Three", "Six"], "Article 218(2) provides for the Chief Election Commissioner as Chairman and four members, each a retired High Court judge from a province.", "Members hold office for three years.")
A("Which Article of the 1973 Constitution lists the duties of the Election Commission to prepare electoral rolls?", "Article 219", ["Article 218", "Article 220", "Article 222"], "Article 219 states the Commission's duties, including the preparation and revision of electoral rolls and the appointment of election tribunals.", "Article 220 requires all executive authorities to help the Commission.")
A("Under which Article can election disputes be decided only by an Election Tribunal?", "Article 225", ["Article 224", "Article 226", "Article 227"], "Article 225 says no election to a House or Provincial Assembly shall be questioned except through an election petition before a tribunal.", "Article 226 says elections other than for Prime Minister and Chief Minister are held by secret ballot.")
A("Which Article provides that all existing laws shall be brought in conformity with the Injunctions of Islam?", "Article 227", ["Article 2A", "Article 228", "Article 230"], "Article 227 requires all existing laws to be brought in conformity with Islamic Injunctions as laid down in the Quran and Sunnah.", "Part IX of the Constitution (Articles 227 to 231) deals with Islamic provisions.")
A("Under which Article is the Council of Islamic Ideology constituted?", "Article 228", ["Article 227", "Article 229", "Article 230"], "Article 228 provides for the Council of Islamic Ideology, with not less than eight and not more than twenty members.", "It advises Parliament and the Provincial Assemblies on whether a law conforms to Islam.")
A("What is the maximum number of members of the Council of Islamic Ideology under Article 228?", "20", ["12", "15", "25"], "Article 228(2) says the Council has at least 8 and at most 20 members appointed by the President.", "The members serve for three years.")
A("Which Article of the 1973 Constitution deals with the emergency due to war or external aggression or internal disturbance?", "Article 232", ["Article 233", "Article 234", "Article 235"], "Article 232 empowers the President to proclaim an emergency if the security of Pakistan is threatened by war, external aggression or internal disturbance.", "Article 233 permits suspension of fundamental rights during an emergency.")
A("Under which Article can fundamental rights be suspended during an emergency?", "Article 233", ["Article 232", "Article 234", "Article 236"], "Article 233 lets the President suspend the enforcement of certain fundamental rights while an emergency is in force.", "Article 234 deals with a failure of the constitutional machinery in a province.")
